import itertools

def autocorr(seq, k):
    n = len(seq)
    return sum(seq[i] * seq[i+k] for i in range(n-k))

def total_cost(seq):
    n = len(seq)
    return sum(autocorr(seq, k)**2 for k in range(1, n))

n = 11

# First, find all sequences with cost <= 23 (no fixed assignments)
solutions = []
for bits in itertools.product([-1, 1], repeat=n):
    seq = list(bits)
    cost = total_cost(seq)
    if cost <= 23:
        solutions.append((seq, cost))

print(f"Total sequences with cost <= 23: {len(solutions)}")
for seq, cost in solutions:
    print(f"  {seq}, cost={cost}")

# Also check what's the minimum possible cost
min_cost = float('inf')
min_seqs = []
for bits in itertools.product([-1, 1], repeat=n):
    seq = list(bits)
    cost = total_cost(seq)
    if cost < min_cost:
        min_cost = cost
        min_seqs = [(seq, cost)]
    elif cost == min_cost:
        min_seqs.append((seq, cost))
print(f"\nMinimum cost: {min_cost}")
print(f"Number of sequences with min cost: {len(min_seqs)}")
for seq, cost in min_seqs[:5]:
    print(f"  {seq}, cost={cost}")

